package com.onlinelearning.service.impl;
import com.onlinelearning.entity.*; import com.onlinelearning.exception.*; import com.onlinelearning.repository.*; import com.onlinelearning.service.*; import lombok.*; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*;
@Service @RequiredArgsConstructor @Transactional public class CourseServiceImpl implements CourseService { private final CourseRepository courses; private final UserRepository users;
 public Course submit(Long id,String email){Course c=owned(id,email); if(c.getStatus()!=CourseStatus.DRAFT&&c.getStatus()!=CourseStatus.REJECTED)throw new ApiException(HttpStatus.CONFLICT,"Only Draft or Rejected courses can be submitted"); c.setStatus(CourseStatus.PENDING_REVIEW);return c;}
 public Course approve(Long id,String email){Course c=pending(id);c.setStatus(CourseStatus.APPROVED);c.setReviewedBy(user(email));c.setRejectionReason(null);return c;}
 public Course reject(Long id,String email,String reason){if(reason==null||reason.isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"Rejection reason is required");Course c=pending(id);c.setStatus(CourseStatus.REJECTED);c.setReviewedBy(user(email));c.setRejectionReason(reason);return c;}
 public Course resubmit(Long id,String email){return submit(id,email);} private Course owned(Long id,String email){Course c=courses.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Course not found"));if(!c.getExpert().getEmail().equalsIgnoreCase(email))throw new ApiException(HttpStatus.FORBIDDEN,"You can only manage your own courses");return c;} private Course pending(Long id){Course c=courses.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Course not found"));if(c.getStatus()!=CourseStatus.PENDING_REVIEW)throw new ApiException(HttpStatus.CONFLICT,"Course is not pending review");return c;} private User user(String email){return users.findByEmailIgnoreCase(email).orElseThrow();}}
